CREATE TABLE IF NOT EXISTS reservation_contacts(mobile VARCHAR(11) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reception_patients(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clinic_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,mobile VARCHAR(11) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY reception_identity(clinic_id,mobile,name),FOREIGN KEY(clinic_id) REFERENCES clinics(id),FOREIGN KEY(parent_id) REFERENCES reception_patients(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reception_delays(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clinic_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,minutes SMALLINT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(clinic_id) REFERENCES clinics(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reception_delay_recipients(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delay_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NOT NULL,mobile VARCHAR(11) NOT NULL,sms_state VARCHAR(20) NOT NULL DEFAULT 'pending',message_id VARCHAR(100) NULL,contacted_at DATETIME NULL,contacted_by BIGINT UNSIGNED NULL,contact_note VARCHAR(500) NULL,UNIQUE KEY delay_booking(delay_id,booking_id),FOREIGN KEY(delay_id) REFERENCES reception_delays(id),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(contacted_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO settings (`key`,value) VALUES('secretary_fee_policy','exempt'),('delay_sms_template','');
